package org.sleepwell.app;

import android.content.Context;
import android.os.Build;
import androidx.test.platform.app.InstrumentationRegistry;
import androidx.test.uiautomator.UiDevice;
import org.junit.*;
import java.util.*;
import static org.junit.Assert.*;

/** Real isolated SQLite/WAV queries; no audio player, recorder or hardware outputs. */
public class FavoriteSoundsStorageTest {
    @Before public void ciOnly()throws Exception{Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();assertEquals("true",InstrumentationRegistry.getArguments().getString("ciReview"));assertTrue(Build.HARDWARE.contains("ranchu")||Build.HARDWARE.contains("goldfish"));assertEquals("1",UiDevice.getInstance(InstrumentationRegistry.getInstrumentation()).executeShellCommand("getprop ro.kernel.qemu").trim());assertFalse(AlarmService.active);assertFalse(TrackingService.running);assertFalse(Prefs.flag(c,"ringing"));}
    private FavoriteSoundRows.Item find(FavoriteSoundRows.Page page,String key){for(FavoriteSoundRows.Item item:page.items)if(item.row.key.equals(key))return item;throw new AssertionError(key);}
    @Test public void globalUnionKeepsIndependentStarsAndDateCategoryFiltersUseActualCaptureTimes()throws Exception{
        try(FavoriteSoundsFixture f=new FavoriteSoundsFixture()){f.standard();FavoriteSoundRows.Page all=FavoriteSoundRows.read(f.context,f.store,new FavoriteSoundRows.Filter(0,"all"),0,f.now);assertEquals(4,all.total);assertEquals(2,all.count("snoring"));assertEquals(1,all.count("speech"));assertEquals(1,all.count("noise"));FavoriteSoundRows.Item event=find(all,"event:"+f.recentEvent.getLong("id")),clip=find(all,"clip:"+f.recentClip.getLong("id"));assertEquals(1000,event.row.target.fromMs);assertEquals(1950,event.row.target.durationMs);assertEquals(0,clip.row.target.fromMs);assertEquals(10000,clip.row.target.durationMs);assertNotNull(event.row.peaks);assertNull(find(all,"event:"+f.analysisEvent.getLong("id")).row.target);FavoriteSoundRows.Page week=FavoriteSoundRows.read(f.context,f.store,new FavoriteSoundRows.Filter(7,"all"),0,f.now);assertEquals(3,week.total);assertEquals(0,week.count("speech"));assertEquals(1,FavoriteSoundRows.read(f.context,f.store,new FavoriteSoundRows.Filter(30,"speech"),0,f.now).total);assertEquals(0,FavoriteSoundRows.read(f.context,f.store,new FavoriteSoundRows.Filter(7,"speech"),0,f.now).total);assertEquals(2,f.store.rows("SELECT id FROM clips").size());assertTrue(f.files.get(0).exists());}
    }
    @Test public void sharedDeletionMissingWavAndEditedPeriodPreserveHonestFavoriteMetadata()throws Exception{
        try(FavoriteSoundsFixture f=new FavoriteSoundsFixture()){f.standard();SoundClips.delete(f.context,f.store,f.recentClip);assertFalse(f.files.get(0).exists());FavoriteSoundRows.Page page=FavoriteSoundRows.read(f.context,f.store,new FavoriteSoundRows.Filter(0,"all"),0,f.now);assertEquals(3,page.total);FavoriteSoundRows.Item estimate=find(page,"event:"+f.recentEvent.getLong("id"));assertTrue(estimate.row.favorite);assertNull(estimate.row.clip);assertNull(estimate.row.target);assertTrue(f.files.get(1).delete());page=FavoriteSoundRows.read(f.context,f.store,new FavoriteSoundRows.Filter(0,"all"),0,f.now);FavoriteSoundRows.Item missing=find(page,"event:"+f.oldEvent.getLong("id"));assertEquals("Recording unavailable",missing.row.audioError);assertNull(missing.row.peaks);RecordDraft edit=new RecordDraft(f.analysis+20000,f.analysis+30000);f.store.getWritableDatabase().insertOrThrow("record_edits",null,Records.values(3,edit,f.now));page=FavoriteSoundRows.read(f.context,f.store,new FavoriteSoundRows.Filter(0,"all"),0,f.now);FavoriteSoundRows.Item outside=find(page,"event:"+f.analysisEvent.getLong("id"));assertTrue(outside.outside);assertEquals("Outside edited sleep period",outside.row.audioError);assertNull(outside.row.target);assertEquals(3,f.store.rows("SELECT id FROM sound_events WHERE favorite=1").size());}
    }
    @Test public void pagingHasNoDuplicateRowsAndUnfavoriteClampsTheLastPageWithoutDeletingRecords()throws Exception{
        try(FavoriteSoundsFixture f=new FavoriteSoundsFixture()){long start=f.night(1,1,200000);for(int n=0;n<51;n++)f.event(1,start+n*2000,"snoring",true);f.store.getWritableDatabase().execSQL("INSERT INTO sessions(id,start,source,zone) VALUES(2,?,'tracked','UTC')",new Object[]{start});f.store.soundEvent(2,start,1950,"snoring",.9,null);f.store.getWritableDatabase().execSQL("UPDATE sound_events SET favorite=1 WHERE session=2");FavoriteSoundRows.Page first=FavoriteSoundRows.read(f.context,f.store,new FavoriteSoundRows.Filter(0,"all"),0,f.now),last=FavoriteSoundRows.read(f.context,f.store,new FavoriteSoundRows.Filter(0,"all"),1,f.now);assertEquals(51,first.total);assertEquals(50,first.items.size());assertTrue(first.older());assertEquals(1,last.items.size());assertFalse(last.older());Set<String> keys=new HashSet<>();for(FavoriteSoundRows.Item row:first.items)assertTrue(keys.add(row.row.key));assertTrue(keys.add(last.items.get(0).row.key));SoundClips.favoriteEvent(f.store,last.items.get(0).row.event,false);FavoriteSoundRows.Page clamped=FavoriteSoundRows.read(f.context,f.store,new FavoriteSoundRows.Filter(0,"all"),1,f.now);assertEquals(0,clamped.page);assertEquals(50,clamped.total);assertEquals(52,f.store.rows("SELECT id FROM sound_events").size());assertEquals(2,f.store.rows("SELECT id FROM sessions").size());}
    }
}
